'use strict';
const {projects,career,intern}=window.PORTFOLIO;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraph=s=>escapeHTML(s).replace(/(https:\/\/[^\s]+)/g,'<a href="$1" target="_blank" rel="noopener noreferrer">$1 ↗</a>');
const labels={engineering:'개발·자동화',analysis:'보안 진단',planning:'기획·컨설팅'};
const art={scable:['SCABLE','SBOM / CODEQL / SCA','{ }'],sbom:['SBOM','GENERATE / MAP / VISUALIZE','↗'],phishime:['Phishime','EXPERIENCE / LEARN / RESPOND','?'],virtual:['보안 컨설팅','JEJU EXPRESS / HANLA KPC','+'],hackathon:['웹 보안 진단','OWASP ZAP / PROOF OF CONCEPT','</>']};
function renderProjects(filter='all'){
 const list=projects.filter(p=>filter==='all'||p.category===filter);
 document.querySelector('#project-grid').innerHTML=list.map(p=>`<button class="project-card" data-project="${p.id}" aria-haspopup="dialog" aria-label="${escapeHTML(p.title)} 상세 보기"><div class="project-art art-${p.id}"><span class="mono">${labels[p.category].toUpperCase()} / ${p.team}</span><span class="art-title ${p.id==='virtual'||p.id==='hackathon'?'korean':''}">${art[p.id][0]}</span><span class="art-mark" aria-hidden="true">${escapeHTML(art[p.id][2])}</span><span class="art-foot"><span>${art[p.id][1]}</span><span>↗</span></span></div><div class="project-meta"><span>${p.date}</span><span>${p.team}</span></div><h3>${p.title}</h3><p>${p.subtitle}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><span class="project-detail-link">프로젝트 상세 보기 <span>↗</span></span></button>`).join('');
 document.querySelector('#project-count').textContent=String(list.length).padStart(2,'0')+' PROJECTS';
}
renderProjects();
document.querySelector('.filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderProjects(b.dataset.filter);});
const dialog=document.querySelector('#project-dialog');let trigger=null;
function openProject(id){const p=projects.find(x=>x.id===id);if(!p)return;document.querySelector('#detail-content').innerHTML=`<p class="eyebrow">${labels[p.category]} / ${p.team}</p><h2 id="detail-title">${p.title}</h2><p class="detail-subtitle">${p.subtitle}</p><div class="detail-meta">${p.date} · ${p.tags.join(' / ')}</div>${p.sections.map(s=>`<section class="detail-section"><h3>${escapeHTML(s.heading)}</h3><p>${paragraph(s.body)}</p></section>`).join('')}${p.id==='scable'?'<a class="text-link" style="display:inline-block;margin-top:30px" href="https://www.youtube.com/@scable-p7f" target="_blank" rel="noopener noreferrer">SCABLE 시연 영상 ↗</a>':''}`;if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;document.querySelector('#close-detail').focus();}
document.querySelector('#project-grid').addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;trigger=b;history.replaceState(null,'','#project-'+b.dataset.project);openProject(b.dataset.project);});
function closeProject(){if(dialog.open)dialog.close();document.body.classList.remove('modal-open');if(location.hash.startsWith('#project-'))history.replaceState(null,'','#projects');trigger?.focus();}
document.querySelector('#close-detail').addEventListener('click',closeProject);dialog.addEventListener('cancel',e=>{e.preventDefault();closeProject();});dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))closeProject();});
if(location.hash.startsWith('#project-'))openProject(location.hash.slice(9));
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#project-'))openProject(location.hash.slice(9));});
const cases=[['탐지 테스트 원인 분석','Linux와 Windows의 실행 로그를 KB와 대조했습니다. 원시 이벤트 수집, Behavioral Indicator 부여, Threat Alert 승격을 구분해 제품 이상 여부와 탐지 조건 차이를 설명했습니다.'],['ANAGENT 반복 오탐 개선','9,475건의 Alert와 접속 이력을 분석하고, 자산 태그와 파일 해시가 모두 일치하는 경우에만 예외를 적용하도록 범위를 제한했습니다.'],['Custom Rule로 보안 공백 보완','정상 자동화 경로 외 접근을 탐지하기 위해, 허용된 Infrabot·Ansible IP가 아닌 Source IP에서 대상 Agent의 22222 포트로 접근할 때 탐지하는 STAR Rule을 설계했습니다.'],['운영 프로세스와 기술자료 문서화','주말 이벤트 처리와 16시 발송 기준을 정리하고 기술 인계자료 3건을 작성했습니다. Purple AI 보조 분석도 원본 로그와 KB를 사람이 검토하도록 기준을 세웠습니다.']];
function bodyParagraphs(s){const sentences=s.split(/(?<=\.)\s+(?=[가-힣A-Z])/);let out=[];for(let i=0;i<sentences.length;i+=3)out.push(sentences.slice(i,i+3).join(' '));return out.map(x=>`<p>${escapeHTML(x)}</p>`).join('');}
document.querySelector('#cases').innerHTML=cases.map(([title,summary],i)=>`<article class="case"><span class="mono">CASE ${String(i+1).padStart(2,'0')}</span><h4>${title}</h4><p>${summary}</p><details><summary>문제 · 분석 · 결과 자세히 보기</summary>${bodyParagraphs(career[i+2].body)}</details></article>`).join('');
document.querySelector('#career-overview').innerHTML=[career[0],career[1],career[6],career[7]].map(s=>`<article><h4>${escapeHTML(s.title.replace(/^\d+\. /,''))}</h4>${bodyParagraphs(s.body)}</article>`).join('');
document.querySelector('#intern-content').innerHTML=intern.map(s=>`<article><h4>${escapeHTML(s.heading)}</h4><p>${paragraph(s.body)}</p></article>`).join('');
function selectTab(b){document.querySelectorAll('.experience-tabs button').forEach(x=>{const active=x===b;x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1;document.getElementById(x.getAttribute('aria-controls')).hidden=!active;});}
document.querySelector('.experience-tabs').addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectTab(b);});
document.querySelector('.experience-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('.experience-tabs button')];const next=e.key==='Home'?tabs[0]:e.key==='End'?tabs[1]:tabs[e.target===tabs[0]?1:0];selectTab(next);next.focus();});
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'닫기':'메뉴';});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='메뉴';}});
